inputs = ['eavjuj', 'jdizh', 'xguwh', 'cf', 'aa']
outputs = ['kgavjuj', 'jdizh', 'exguwh', 'cf', 'aa']

print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"Example {i}: '{inp}' -> '{outp}'")
        # Find where they differ
        min_len = min(len(inp), len(outp))
        diff_pos = -1
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_pos = j
                break
        if diff_pos == -1:
            if len(inp) != len(outp):
                diff_pos = min_len
        print(f"  Difference at position {diff_pos}")
        if diff_pos >= 0 and diff_pos < len(outp):
            print(f"  New character at pos {diff_pos}: '{outp[diff_pos]}'")
        if len(outp) > len(inp):
            print(f"  Length increased by {len(outp) - len(inp)}")
        elif len(inp) > len(outp):
            print(f"  Length decreased by {len(inp) - len(outp)}")
        print()

