    print(f"\n{i}: '{inp}' -> '{outp}'")
    if inp == outp:
        print("  No change")
    else:
        max_len = max(len(inp), len(outp))
        for pos in range(max_len):
            in_char = inp[pos] if pos < len(inp) else None
            out_char = outp[pos] if pos < len(outp) else None
            if in_char != out_char:
                print(f"  Position {pos}: '{in_char}' -> '{out_char}'")

